def forward(groups):
    canonical_value = int(groups[1])
    layout_value = int(groups[0])
    return {'stored': [canonical_value], 'layout': [layout_value]}

def inverse(record):
    canonical_value = int(record['stored'][0])
    layout_value = int(record['layout'][0])
    return f"{layout_value}({canonical_value})"
